SELECT id, title, detail, category, priority, due_date, completed, completed_at, deleted_at, created_at, updated_at FROM todos
AND deleted_at IS NULL
title LIKE CONCAT('%', #{keyword}, '%')
AND category = #{category}
AND due_date IS NOT NULL AND due_date >= #{from}
AND due_date IS NOT NULL AND due_date <= #{to}
ORDER BY due_date DESC
ORDER BY due_date ASC
